    nome: "Descida do lobo gélido",
    causa: { tipo: "clima", id: "nevasca", zonas: ["trono_congelado"] },
    saemDe: ["trono_congelado"],
    especies: ["lobo_gelido"],
    vaoPara: ["vale_das_geleiras", "pantano_bruma"],
